from collections import defaultdict


class SuffixTreeNode:
    def __init__(self):
        self.children = defaultdict(SuffixTreeNode)
        self.indexes = []

    def insert(self, word, index):
        self.indexes.append(index)
        if len(word) > 0:
            head = word[0]
            tail = word[1:]
            if head not in self.children:
                self.children[head] = SuffixTreeNode()
            self.children[head].insert(tail, index + 1)

    def search(self, word):
        if len(word) == 0:
            return self.indexes
        head = word[0]
        tail = word[1:]
        if head in self.children:
            return self.children[head].search(tail)
        else:
            return []

    def get_substrings(self, string):
        substrings = []
        for i in range(len(string)):
            substrings.extend(self.search(string[i:]))
        return substrings


def is_formed_by_substrings(string):
    suffix_tree = SuffixTreeNode()
    n = len(string)
    for i in range(n):
        suffix_tree.insert(string[i:], i)
    substrings = suffix_tree.get_substrings(string)
    sorted_substrings = sorted(substrings)
    return sorted_substrings == list(range(n))


# Example usage:
test_string = "stackoverflow"
result = is_formed_by_substrings(test_string)
print(result)  # Output: True
```

The code above utilizes a `SuffixTreeNode` class to construct a Suffix Tree. The `insert` method is used to insert substrings into the tree, while the `search` method is used to search for a given substring in the tree. The `get_substrings` method returns all the substrings of a given string using the Suffix Tree.

The `is_formed_by_substrings` function takes a string as input and constructs a suffix tree from the string. It then retrieves all the substrings of the input string using the `get_substrings` method. These substrings are sorted and compared with a list of indices from 0 to n-1 (where n is the length of the input string). If the sorted list of substrings is equal to the list of indices, it means that the input string can be formed by concatenating its substrings. Otherwise, it cannot be formed in that way.

