            if len(node.children) > 2:
                return
            if len(node.children) == 2:
                distinct_char_count += 1
            if distinct_char_count <= 2 and node.end >= 0:
                substring = self.string[node.start: node.end+1]
                if len(substring) > len(traverse.longest_substring):
                    traverse.longest_substring = substring

            for child in node.children.values():
                traverse(child, distinct_char_count, path + [child])

